INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Datenschutzgesetze > Personenbezogene Daten
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind personenbezogene Daten nach Datenschutzgesetzen immer direkt einer Person zuordenbar?', 2, '[{"text": "Ja", "correct": true, "because": "Personenbezogene Daten müssen eine Person identifizieren"}, {"text": "Nein", "correct": false, "because": "Direkte Zuordenbarkeit ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können anonymisierte Daten als personenbezogene Daten gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Anonymisierte Daten sind nicht mehr identifizierbar"}, {"text": "Ja", "correct": false, "because": "Anonymisierung entfernt Personenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen personenbezogene Daten immer physische Merkmale wie Fingerabdrücke enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Namen oder E-Mail-Adressen sind personenbezogen"}, {"text": "Ja", "correct": false, "because": "Vielfalt der Daten ist groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Verarbeitung personenbezogener Daten ohne Einwilligung rechtmäßig sein?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Grundlagen wie Vertragserfüllung erlauben es"}, {"text": "Nein", "correct": false, "because": "Einwilligung nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Unternehmen verpflichtet, personenbezogene Daten bei Nichtnutzung zu löschen?', 2, '[{"text": "Ja", "correct": true, "because": "Datenschutzgesetze fordern Löschung bei Zweckentfall"}, {"text": "Nein", "correct": false, "because": "Löschpflicht ist gesetzlich geregelt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Definition beschreibt personenbezogene Daten am besten?', 2, '[{"text": "Informationen, die eine Person identifizieren", "correct": true, "because": "Kern der gesetzlichen Definition"}, {"text": "Öffentliche Daten über Unternehmen", "correct": false, "because": "Nicht personenbezogen"}, {"text": "Technische Systemdaten", "correct": false, "because": "Kein Personenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt den Umgang mit personenbezogenen Daten primär auf EU-Ebene?', 3, '[{"text": "DSGVO", "correct": true, "because": "Datenschutz-Grundverordnung gilt EU-weit"}, {"text": "BDSG", "correct": false, "because": "Nationales Gesetz"}, {"text": "GDPR", "correct": false, "because": "Englischer Begriff für DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zählt eindeutig zu personenbezogenen Daten?', 2, '[{"text": "E-Mail-Adresse", "correct": true, "because": "Identifiziert eine Person"}, {"text": "Unternehmensadresse", "correct": false, "because": "Nicht personenbezogen"}, {"text": "Server-Logs", "correct": false, "because": "Nur bedingt personenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist bei der Verarbeitung personenbezogener Daten rechtlich vorgeschrieben?', 2, '[{"text": "Datensparsamkeit", "correct": true, "because": "Nur notwendige Daten erheben"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Widerspricht Gesetz"}, {"text": "Unbefristete Speicherung", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko besteht bei unsachgemäßer Handhabung personenbezogener Daten?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Datenschutzgesetze strafbar"}, {"text": "Langsame Systeme", "correct": false, "because": "Kein direkter Zusammenhang"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Kein Sicherheitsrisiko"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Daten gelten als personenbezogene Daten nach Datenschutzgesetzen?', 4, '[{"text": "Name", "correct": true, "because": "Identifiziert eine Person"}, {"text": "Telefonnummer", "correct": true, "because": "Zuordenbar zu einer Person"}, {"text": "IP-Adresse", "correct": true, "because": "Kann personenbezogen sein"}, {"text": "Wetterdaten", "correct": false, "because": "Kein Personenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Grundlagen erlauben die Verarbeitung personenbezogener Daten?', 3, '[{"text": "Einwilligung", "correct": true, "because": "Freiwillige Zustimmung"}, {"text": "Vertragserfüllung", "correct": true, "because": "Notwendig für Verträge"}, {"text": "Rechtliche Verpflichtung", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen personenbezogene Daten?', 4, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Zugriffskontrolle", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "Datensparsamkeit", "correct": true, "because": "Reduziert erhobene Daten"}, {"text": "Öffentliche Speicherung", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen Datenschutzgesetze bei personenbezogenen Daten haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Gesetzliche Strafen"}, {"text": "Reputationsverlust", "correct": true, "because": "Vertrauen schwindet"}, {"text": "Rechtliche Schritte", "correct": true, "because": "Betroffene können klagen"}, {"text": "Verbesserte Performance", "correct": false, "because": "Keine positive Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten bei der Verarbeitung personenbezogener Daten beachtet werden?', 3, '[{"text": "Rechtmäßigkeit", "correct": true, "because": "Gesetzliche Grundlage nötig"}, {"text": "Transparenz", "correct": true, "because": "Nutzer müssen informiert werden"}, {"text": "Zweckbindung", "correct": true, "because": "Nur für festgelegte Zwecke"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Verboten"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Personenbezogene Daten identifizieren eine Person. b) Anonymisierte Daten sind personenbezogen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identifikation ja, anonymisiert nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO regelt personenbezogene Daten EU-weit. b) Einwilligung ist immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO ja, Einwilligung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt personenbezogene Daten. b) Physische Merkmale sind zwingend erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ja, Merkmale nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Datensparsamkeit ist ein Prinzip bei personenbezogenen Daten. b) Daten müssen unbefristet gespeichert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datensparsamkeit ja, unbefristet nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bußgelder drohen bei Verstößen gegen Datenschutzgesetze. b) Personenbezogene Daten sind nur Namen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, Daten vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

